 form=await cardGeneratorRules('0');assert.equal(await page.evaluate(()=>typeof toRulesAssetId),'string');assert.equal(await page.evaluate(()=>toRulesAssetId),'0');assert.equal(await form.locator('.to-rule-row').count(),1);assert.equal(ruleHoursNumber(await form.locator('.to-rule-meter').inputValue()),900);await form.locator('[data-to-rule-preset]').selectOption('250');await saveGeneratorRules(form);assert.deepEqual(await page.evaluate(()=>data.generators[0].maintenanceRules),numeric);assert.equal(await page.evaluate(()=>data.generators[1].maintenanceRules[0].id),'0');assert.equal(await page.evaluate(()=>data.generators[1].maintenanceRules[0].hours),250);assert.equal(await page.evaluate(()=>JSON.stringify([data.genRecords,data.parts,data.partMovements,data.generatorMaintenancePlans])),before.facts);
