 const review=await page.evaluate(id=>{const preview=GeneratorMaintenance.preview(data,{action:'approve',planId:id,date:gmUiToday(),document:'Synthetic inactive ZIP decision',reason:'Synthetic inactive ZIP validation'},{today:gmUiToday()});return {canApply:preview.canApply,codes:preview.issues.map(issue=>issue.code)};},id);assert.equal(review.canApply,false);assert.equal(review.codes.filter(code=>code==='MAINTENANCE_PART').length,2);assert.equal(await page.evaluate(()=>JSON.stringify(data)),before);assert.equal(await page.evaluate(()=>__writes+__raw.length+__commands.length),0);
